/**
 * Parses a QR code generated by `/remote-control` in Puku CLI into a
 * sessionId + token pair. Mirrors the Flutter app's
 * RemoteSessionPairingEntity.parse so either app can scan the same code.
 *
 * Accepted formats:
 *  - a URI with query params `s`/`sessionId` and `t`/`token`
 *  - a JSON object `{ sessionId, token }` or `{ s, t }`
 *  - a `key=value` list separated by `&`, `;`, or newlines
 */
export interface PairingPayload {
  sessionId: string;
  token: string;
}

function isPresent(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

function tryParseUri(value: string): PairingPayload | null {
  try {
    const url = new URL(value);
    const sessionId = url.searchParams.get('s') || url.searchParams.get('sessionId');
    const token = url.searchParams.get('t') || url.searchParams.get('token');
    if (isPresent(sessionId) && isPresent(token)) {
      return { sessionId, token };
    }
  } catch {
    // Not a valid absolute URI; fall through to the other formats.
  }
  return null;
}

function tryParseJson(value: string): PairingPayload | null {
  try {
    const json = JSON.parse(value);
    if (json && typeof json === 'object') {
      const sessionId = json.sessionId ?? json.s;
      const token = json.token ?? json.t;
      if (isPresent(sessionId) && isPresent(token)) {
        return { sessionId, token };
      }
    }
  } catch {
    // Not JSON.
  }
  return null;
}

function tryParseKeyValuePairs(value: string): PairingPayload | null {
  const normalized = value.replace(/\n/g, '&').replace(/;/g, '&');
  const pairs: Record<string, string> = {};
  for (const segment of normalized.split('&')) {
    const index = segment.indexOf('=');
    if (index <= 0) continue;
    pairs[segment.slice(0, index).trim()] = segment.slice(index + 1).trim();
  }
  const sessionId = pairs.sessionId ?? pairs.s;
  const token = pairs.token ?? pairs.t;
  if (isPresent(sessionId) && isPresent(token)) {
    return { sessionId, token };
  }
  return null;
}

export function parsePairingPayload(rawValue: string): PairingPayload | null {
  const value = rawValue.trim();
  if (!value) return null;

  return tryParseUri(value) || tryParseJson(value) || tryParseKeyValuePairs(value);
}
